def transform(grid):
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(len(grid)) for c in range(len(grid[0])) if grid[r][c] not in (0, 5)]
    for r, c, color in markers:
        same_diagonal = (r < 5) == (c < 5)
        for y in range(3, 7):
            for x in range(3, 7):
                if ((y < 5) == (x < 5)) == same_diagonal:
                    out[y][x] = color
    return out
